"""Static DAG validation and level planning for workflow definitions.

The planner only analyzes dependencies; it never executes tasks. Given a
definition document it either produces deterministic execution levels or a
single, deterministically chosen error message.
"""
import json
from collections import Counter, defaultdict


class _CannotRead(Exception):
    """The definition file could not be read."""


class _InvalidJson(Exception):
    """The definition file is not valid JSON."""


class _InvalidDefinition(Exception):
    """The JSON value does not have the required definition structure."""


def _read_document(path: str):
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:  # missing file, permission denied, directory, ...
        raise _CannotRead(path) from exc
    try:
        return json.loads(raw)
    except ValueError as exc:  # json.JSONDecodeError and UnicodeDecodeError
        raise _InvalidJson from exc


def _parse_tasks(document):
    # Top level must be an object containing exactly one key: "tasks".
    if not isinstance(document, dict) or set(document) != {"tasks"}:
        raise _InvalidDefinition
    raw_tasks = document["tasks"]
    if not isinstance(raw_tasks, list):
        raise _InvalidDefinition

    entries = []
    for task in raw_tasks:
        if not isinstance(task, dict):
            raise _InvalidDefinition
        if not set(task) <= {"id", "depends_on"}:
            raise _InvalidDefinition
        task_id = task.get("id")
        if not isinstance(task_id, str) or task_id == "":
            raise _InvalidDefinition
        depends_on = task.get("depends_on", [])
        if not isinstance(depends_on, list) or not all(
            isinstance(dep, str) for dep in depends_on
        ):
            raise _InvalidDefinition
        entries.append((task_id, list(depends_on)))
    return entries


def _reachable(adj, start):
    seen = set()
    stack = [start]
    while stack:
        node = stack.pop()
        for nxt in adj.get(node, ()):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return seen


def _graph_error(entries):
    """Return the single error message to report, or None when the DAG is valid.

    Every structural graph problem is keyed by the (task id, dependency id)
    pair it involves and candidates are compared by Unicode code point order,
    so the choice never depends on input ordering.
    """
    counts = Counter(task_id for task_id, _ in entries)
    known = set(counts)

    # (first id, second id, kind rank, message); kind rank only breaks exact
    # pair ties deterministically.
    candidates = []
    for task_id in counts:
        if counts[task_id] > 1:
            candidates.append((task_id, "", 0, f"duplicate task id: {task_id}"))

    adj = defaultdict(set)
    for task_id, deps in entries:
        for dep in set(deps):
            if dep == task_id:
                candidates.append(
                    (task_id, task_id, 1, f"self dependency: {task_id}")
                )
            elif dep not in known:
                candidates.append(
                    (task_id, dep, 2, f"unknown dependency: {task_id} -> {dep}")
                )
            else:
                adj[task_id].add(dep)

    # An edge u -> v (u != v) participates in a cycle iff v can reach u.
    reach_cache = {}
    cycle_key = None
    for task_id, deps in adj.items():
        for dep in deps:
            if dep not in reach_cache:
                reach_cache[dep] = _reachable(adj, dep)
            if task_id in reach_cache[dep]:
                key = (task_id, dep)
                if cycle_key is None or key < cycle_key:
                    cycle_key = key
    if cycle_key is not None:
        candidates.append(
            (cycle_key[0], cycle_key[1], 3, "cycle detected")
        )

    if not candidates:
        return None
    return min(candidates, key=lambda item: item[:3])[3]


def _build_levels(entries):
    deps_by_task = {}
    for task_id, deps in entries:
        deps_by_task[task_id] = set(deps)

    depth = {}
    for root in deps_by_task:
        if root in depth:
            continue
        stack = [(root, False)]
        while stack:
            node, done = stack.pop()
            if done:
                deps = deps_by_task[node]
                depth[node] = 0 if not deps else 1 + max(depth[d] for d in deps)
            elif node not in depth:
                stack.append((node, True))
                for dep in deps_by_task[node]:
                    if dep not in depth:
                        stack.append((dep, False))

    levels = []
    for task_id, level in depth.items():
        while len(levels) <= level:
            levels.append([])
        levels[level].append(task_id)
    for level in levels:
        level.sort()  # Unicode code point order
    return levels


def _render(levels) -> str:
    return json.dumps({"levels": levels}, ensure_ascii=False, separators=(",", ":"))


def _load_entries(path: str, stderr):
    """Read and fully validate a definition file.

    Returns ``(entries, None)`` on success. On failure writes the single
    diagnostic line to ``stderr`` and returns ``(None, exit_code)``; the
    error priority, texts, and codes are the ones ``plan`` has always
    reported, and are shared with the ``schedule`` command.
    """
    try:
        document = _read_document(path)
    except _CannotRead:
        stderr.write(f"cannot read definition: {path}\n")
        return None, 1
    except _InvalidJson:
        stderr.write("invalid json\n")
        return None, 2

    try:
        entries = _parse_tasks(document)
    except _InvalidDefinition:
        stderr.write("invalid definition\n")
        return None, 2

    error = _graph_error(entries)
    if error is not None:
        stderr.write(error + "\n")
        return None, 2

    return entries, None


def run(path: str, stdout, stderr) -> int:
    """Execute the plan command, writing to the provided text streams."""
    entries, code = _load_entries(path, stderr)
    if entries is None:
        return code
    stdout.write(_render(_build_levels(entries)) + "\n")
    return 0

"""Shared black-box test infrastructure.

Tests enter through the documented public entry point
(``python -m workflow_orchestrator``) with definition files on disk, and
assert on the process exit status and raw stdout/stderr bytes.

The subprocess environment is whitelisted and pinned so results cannot
depend on the invoking machine's locale, Python hash seed, or directory
ordering:

* ``LC_ALL=LANG=C`` with UTF-8 mode / IO encoding forced on (a test-time
  configuration; the installed library keeps zero runtime dependencies),
* a fixed ``PYTHONHASHSEED`` by default, with dedicated tests varying it,
* ``cwd`` and ``PYTHONPATH`` pinned at the repository root.
"""
import json
import os
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

import pytest

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

BASE_ENV = {
    "PATH": os.environ.get("PATH", ""),
    "HOME": os.environ.get("HOME", "/tmp"),
    "TMPDIR": os.environ.get("TMPDIR", "/tmp"),
    "LC_ALL": "C",
    "LANG": "C",
    # Pin the standard stream encoding to UTF-8 on every supported Python
    # regardless of the C locale above.
    "PYTHONUTF8": "1",
    "PYTHONIOENCODING": "utf-8",
    "PYTHONHASHSEED": "0",
    "PYTHONPATH": REPO_ROOT,
}


def make_env(**overrides):
    """A subprocess environment based on BASE_ENV.

    A value of None removes the key entirely (e.g. PYTHONHASHSEED=None to
    let the interpreter pick a random seed).
    """
    env = dict(BASE_ENV)
    for key, value in overrides.items():
        if value is None:
            env.pop(key, None)
        else:
            env[key] = value
    return env


class CliRunner:
    """Run the public CLI as a subprocess and capture raw byte streams."""

    def run(self, argv, *, env=None, timeout=120):
        return subprocess.run(
            [sys.executable, "-m", "workflow_orchestrator", *argv],
            cwd=REPO_ROOT,
            env=BASE_ENV if env is None else env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
        )

    def plan(self, path, *, env=None, timeout=120):
        return self.run(["plan", str(path)], env=env, timeout=timeout)

    def schedule(self, path, max_parallel, *, env=None, timeout=120):
        return self.run(
            ["schedule", str(path), str(max_parallel)], env=env, timeout=timeout
        )

    def plan_many(self, paths, *, env=None, timeout=120, workers=8):
        """Run plan over many definition files concurrently, in order.

        Subprocess startup dominates these cases; waiting on child processes
        releases the GIL, so a thread pool keeps the suite fast without any
        shared state between runs.
        """
        paths = list(paths)
        with ThreadPoolExecutor(max_workers=workers) as pool:
            return list(
                pool.map(
                    lambda p: self.plan(p, env=env, timeout=timeout), paths
                )
            )


def render_levels(levels) -> bytes:
    """The exact compact success-output byte contract (plus newline)."""
    return (
        json.dumps(
            {"levels": levels}, ensure_ascii=False, separators=(",", ":")
        )
        + "\n"
    ).encode("utf-8")


def render_batches(batches) -> bytes:
    """The exact compact schedule success-output byte contract (plus newline)."""
    return (
        json.dumps(
            {"batches": batches}, ensure_ascii=False, separators=(",", ":")
        )
        + "\n"
    ).encode("utf-8")


@pytest.fixture(scope="session")
def cli():
    return CliRunner()


@pytest.fixture
def write_def(tmp_path):
    """Write a definition document (or raw bytes) and return its path."""
    counter = 0

    def _write(doc=None, *, raw=None, name=None, indent=False):
        nonlocal counter
        path = tmp_path / (name or f"definition-{counter}.json")
        counter += 1
        if raw is not None:
            path.write_bytes(raw)
        else:
            text = json.dumps(doc, ensure_ascii=False, indent=2 if indent else None)
            path.write_text(text, encoding="utf-8")
        return path

    return _write


def assert_success(result, expected_stdout: bytes):
    """Assert the full success contract: rc 0, exact stdout, empty stderr."""
    assert result.returncode == 0, result.stderr
    assert result.stdout == expected_stdout
    assert result.stderr == b""


def assert_failure(result, expected_stderr: bytes, code=2):
    """Assert the full failure contract: given rc, empty stdout, one diagnostic."""
    assert result.returncode == code
    assert result.stdout == b"", "failure path must write nothing to stdout"
    assert result.stderr == expected_stderr
    # Every documented failure reports exactly one line on stderr.
    assert expected_stderr.endswith(b"\n")
    assert expected_stderr.count(b"\n") == 1

