        if not isinstance(task, dict):
            raise InvalidDefinition
        if not set(task) <= {"id", "depends_on"}:
            raise InvalidDefinition
        task_id = task.get("id")
        if not isinstance(task_id, str) or task_id == "":
            raise InvalidDefinition
